using System;

namespace Screenbox.Core.Models;

/// <summary>
/// Disposable, refetchable online-metadata cache for a single library folder. Unlike
/// <see cref="FolderMetadataDto"/>, everything here can be regenerated by scraping again, so the
/// backing table is dropped and recreated on schema drift rather than migrated in place.
/// </summary>
public sealed class FolderScrapeCacheDto
{
    /// <summary>Absolute path of the folder. Primary key.</summary>
    public string Path { get; set; } = string.Empty;

    /// <summary>Identifier of the metadata provider that produced this entry, for example "anilist".</summary>
    public string? Provider { get; set; }

    /// <summary>The matched title's identifier within <see cref="Provider"/>.</summary>
    public string? ProviderId { get; set; }

    /// <summary>Synopsis or description text returned by the provider.</summary>
    public string? Synopsis { get; set; }

    /// <summary>Release year returned by the provider.</summary>
    public int? Year { get; set; }

    /// <summary>File name within the local Artwork folder for a scraped poster. Never an absolute path.</summary>
    public string? ScrapedPoster { get; set; }

    /// <summary>When this entry was last refreshed from the provider.</summary>
    public DateTimeOffset? LastScraped { get; set; }
}
